// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        c.Command{value: 1 ether}(address(0), "");
        uint256 balanceBefore = address(c).balance;
        address recipient = address(0x1234);
        vm.deal(address(this), address(c).balance);
        vm.prank(address(this));
        bool ok = false;
        try c.multiplicate{value: address(c).balance}(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(ok && balanceAfter == 0);
    }
}
